#!/usr/bin/env python3
"""Regenerate deps/wheels.lock: the pinned wheels deps/fetch_wheels.sh unpacks.

Run this only when bumping a version below. The wheels are unpacked whole into
external/wheels: the C++ build uses their native libraries and headers, and the
GPU reference tools import their Python packages from the same files.
"""

import json
import re
import urllib.request
from pathlib import Path

TORCH_VERSION = "2.10.0"
TORCH_CUDA = "cu130"
# Arrow libraries are linked by exact file name (libarrow.so.<major>00): when the
# major version changes, update ARROW_SOVERSION in cc/Makefile too.
PYARROW_VERSION = "25.0.1"
# Python tag of the torch and pyarrow wheels. Their Python packages only load in
# this CPython version, so the venvs that import external/wheels
# (scripts/gpu/setup_python_venv.sh, scripts/qualification/setup_python.sh)
# must use it too.
WHEEL_PYTHON = "cp312"

# lock platform -> wheel platform tags it accepts (any glibc / macOS version)
PLATFORMS = {
    "linux-x86_64": r"manylinux[0-9_]*_x86_64",
    "linux-aarch64": r"manylinux[0-9_]*_aarch64",
    "macos-arm64": r"macosx_[0-9]+_[0-9]+_arm64",
}
TORCH_INDEX = "https://download.pytorch.org/whl"
LOCK = Path(__file__).resolve().parent / "wheels.lock"


def fetch(url):
    request = urllib.request.Request(url, headers={"User-Agent": "curl/8"})
    with urllib.request.urlopen(request) as response:
        return response.read().decode()


def parse_wheel(filename):
    """Split a wheel filename into (version, build, python, abi, platform tags)."""
    parts = filename.removesuffix(".whl").split("-")
    build = int(parts[2]) if len(parts) == 6 else 0
    return parts[1], build, parts[-3], parts[-2], parts[-1].split(".")


def on_platform(filename, platform):
    *_, tags = parse_wheel(filename)
    return any(re.fullmatch(PLATFORMS[platform], tag) for tag in tags)


def torch_wheel(variant, platform):
    """Return (url, sha256) of the torch wheel from PyTorch's index."""
    local = "cpu" if variant == "cpu" else TORCH_CUDA
    page = fetch(f"{TORCH_INDEX}/{local}/torch/")
    # macOS wheels carry no local version suffix (+cpu); Linux wheels do.
    versions = {TORCH_VERSION, f"{TORCH_VERSION}+{local}"}
    matches = []
    for name, sha in re.findall(r'href="[^"]*?/(torch-[^"#/]+\.whl)#sha256=([0-9a-f]{64})"', page):
        name = name.replace("%2B", "+")
        version, build, python, _, _ = parse_wheel(name)
        if version in versions and python == WHEEL_PYTHON and on_platform(name, platform):
            # Prefer the local-suffixed build, then the highest build tag (as pip does).
            matches.append(("+" in version, build, name, sha))
    if not matches:
        raise SystemExit(f"no torch {TORCH_VERSION} {local} wheel for {platform}")
    *_, name, sha = max(matches)
    return f"{TORCH_INDEX}/{local}/{name.replace('+', '%2B')}", sha


def pypi_wheel(package, version, platform, python=None):
    """Return (url, sha256) of a PyPI wheel for platform (and python tag, if given)."""
    files = json.loads(fetch(f"https://pypi.org/pypi/{package}/{version}/json"))["urls"]
    for f in files:
        name = f["filename"]
        if name.endswith(".whl") and on_platform(name, platform) and \
                (python is None or parse_wheel(name)[2] == python):
            return f["url"], f["digests"]["sha256"]
    raise SystemExit(f"no {platform} wheel for {package}=={version}")


def nvidia_pins(torch_url):
    """Exact nvidia-* pins from the torch wheel's metadata."""
    metadata = fetch(torch_url + ".metadata")
    pins = re.findall(r"^Requires-Dist: (nvidia-[a-z0-9-]+)==([^;\s]+)", metadata, re.M)
    if not pins:
        raise SystemExit(f"no nvidia-* pins in {torch_url}.metadata")
    return pins


def main():
    lines = [
        "# Generated by deps/lock_wheels.py -- do not edit by hand.",
        f"# torch {TORCH_VERSION} (cpu, {TORCH_CUDA}), pyarrow {PYARROW_VERSION}, {WHEEL_PYTHON}",
        "# <platform> <variant> <sha256> <url>",
    ]
    for platform in PLATFORMS:
        variants = ["cpu", "cuda"] if platform.startswith("linux") else ["cpu"]
        for variant in variants:
            url, sha = torch_wheel(variant, platform)
            lines.append(f"{platform} {variant} {sha} {url}")
            if variant == "cuda":
                for package, version in nvidia_pins(url):
                    nv_url, nv_sha = pypi_wheel(package, version, platform)
                    lines.append(f"{platform} cuda {nv_sha} {nv_url}")
        url, sha = pypi_wheel("pyarrow", PYARROW_VERSION, platform, python=WHEEL_PYTHON)
        lines.append(f"{platform} any {sha} {url}")
    LOCK.write_text("\n".join(lines) + "\n")
    print(f"wrote {LOCK} ({len(lines) - 3} wheels)")


if __name__ == "__main__":
    main()
